mapper.sql:
WHERE m.deleted = 0 AND m.tenant_id = #{tenantId}
AND m.first_customer_time >= #{startTime}
AND m.first_customer_time < #{endTime}
AND m.room_id = #{roomId}
AND m.first_reply_user = #{memberUser}
AND m.first_customer_user = #{customerUser}

    AND m.response_status IN
    #{s}


    AND c.content LIKE CONCAT('%', #{keyword}, '%')

mapper.select:
SELECT * FROM ( SELECT m.id AS id, m.room_id AS room_id, m.chat_name AS chat_name, m.first_customer_msg_id AS first_customer_msg_id, m.first_customer_user AS first_customer_user, m.first_customer_time AS first_customer_time, m.first_reply_msg_id AS first_reply_msg_id, m.first_reply_user AS first_reply_user, m.first_reply_name AS first_reply_name, m.first_reply_time AS first_reply_time, m.response_seconds AS response_seconds, m.working_seconds AS working_seconds, m.response_status AS response_status, m.replied AS replied, c.from_name AS customer_name, c.content AS customer_content, c.msg_type AS customer_msg_type, r.content AS reply_content, r.msg_type AS reply_msg_type, ROW_NUMBER() OVER (PARTITION BY m.room_id ORDER BY m.first_customer_time DESC, m.id DESC) AS rn FROM work_wx_response_metric m LEFT JOIN work_wx_message c ON c.msg_id = m.first_customer_msg_id AND c.deleted = 0 LEFT JOIN work_wx_message r ON r.msg_id = m.first_reply_msg_id AND r.deleted = 0
) t WHERE t.rn = 1
ORDER BY t.response_seconds DESC ORDER BY (t.replied = 0) DESC, t.first_customer_time ASC ORDER BY t.first_customer_time DESC
LIMIT #{offset}, #{limit}
